from collections import Counter

def _components(g, bg):
    h, w = len(g), len(g[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg or (r, c) in seen:
                continue
            color, stack, cells = g[r][c], [(r, c)], set()
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen
                            and g[yy][xx] == color):
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            out.append({'color': color, 'cells': cells, 'r0': min(rs),
                        'r1': max(rs), 'c0': min(cs), 'c1': max(cs)})
    return out

def _shape(obj):
    return frozenset((r-obj['r0'], c-obj['c0']) for r,c in obj['cells'])

def _corner_frame(obj):
    cells = obj['cells']
    r0,r1,c0,c1 = obj['r0'],obj['r1'],obj['c0'],obj['c1']
    if r1-r0+1 < 4 or c1-c0+1 < 4:
        return False
    horizontal = []
    if all((r0,c) in cells for c in range(c0,c1+1)): horizontal.append(r0)
    if all((r1,c) in cells for c in range(c0,c1+1)): horizontal.append(r1)
    vertical = []
    if all((r,c0) in cells for r in range(r0,r1+1)): vertical.append(c0)
    if all((r,c1) in cells for r in range(r0,r1+1)): vertical.append(c1)
    if not horizontal or not vertical:
        return False
    # The component consists of one horizontal and one vertical edge, meeting at a corner.
    allowed = set()
    for rr in horizontal:
        for c in range(c0,c1+1): allowed.add((rr,c))
    for cc in vertical:
        for r in range(r0,r1+1): allowed.add((r,cc))
    return cells <= allowed and any((r,c) in cells for r in horizontal for c in vertical)

def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    comps = _components(g, bg)
    for frame in comps:
        if not _corner_frame(frame):
            continue
        enclosed = [o for o in comps if o is not frame and
                    frame['r0'] <= o['r0'] and o['r1'] <= frame['r1'] and
                    frame['c0'] <= o['c0'] and o['c1'] <= frame['c1']]
        for ref in enclosed:
            sig = _shape(ref)
            matches = [o for o in comps if o is not frame and o is not ref and
                       not (frame['r0'] <= o['r0'] and o['r1'] <= frame['r1'] and
                            frame['c0'] <= o['c0'] and o['c1'] <= frame['c1'])
                       and _shape(o) == sig]
            if matches:
                # There is one matching object; recolor it using the frame's color.
                target = matches[0]
                for r,c in target['cells']:
                    g[r][c] = frame['color']
                return g
    return g

